#!/usr/bin/env python3
import base64
import json
import os
import stat
from pathlib import Path

REQUESTED = Path("/root/.msf4/loot/20261022133215_default_192.168.5.5_grafana.loot_460787.txt")


def inspect_file(path):
    record = {"path": str(path), "resolved_path": None, "access": "unknown"}
    try:
        record["resolved_path"] = str(path.resolve(strict=False))
        info = path.stat()
        record["file_type"] = "regular" if stat.S_ISREG(info.st_mode) else "non_regular"
        record["size_bytes"] = info.st_size
        data = path.read_bytes()
        record.update({
            "access": "readable",
            "content_utf8": data.decode("utf-8", errors="replace"),
            "content_base64": base64.b64encode(data).decode("ascii"),
            "content_bytes": len(data),
            "utf8_decode_errors_replaced": False,
        })
        try:
            data.decode("utf-8")
        except UnicodeDecodeError:
            record["utf8_decode_errors_replaced"] = True
    except FileNotFoundError as exc:
        record.update({"access": "unavailable", "error_type": type(exc).__name__, "error": str(exc)})
    except OSError as exc:
        record.update({"access": "inaccessible", "error_type": type(exc).__name__, "error": str(exc)})
    return record


result = {
    "evidence_type": "local_filesystem_inspection",
    "provenance": "Content, if present, was read from the executor filesystem at the recorded path; the filename alone does not establish target attribution.",
    "requested_file": inspect_file(REQUESTED),
    "same_directory_grafana_candidates": [],
    "candidate_directory_access": "not_needed",
}

if result["requested_file"]["access"] != "readable":
    directory = REQUESTED.parent
    try:
        entries = sorted(directory.iterdir(), key=lambda item: item.name)
        result["candidate_directory_access"] = "readable"
        for entry in entries:
            if entry == REQUESTED or "grafana" not in entry.name.lower():
                continue
            try:
                if entry.is_file():
                    result["same_directory_grafana_candidates"].append(inspect_file(entry))
            except OSError as exc:
                result["same_directory_grafana_candidates"].append({
                    "path": str(entry),
                    "access": "inaccessible",
                    "error_type": type(exc).__name__,
                    "error": str(exc),
                })
    except OSError as exc:
        result["candidate_directory_access"] = "inaccessible"
        result["candidate_directory_error"] = {"error_type": type(exc).__name__, "error": str(exc)}

print(json.dumps(result, ensure_ascii=False, sort_keys=True))
